Rules.InvariantScript:
Set(varIsNewAsset, IsBlank(varEditAsset.'Id (ID)'));
// Preload the holder from the existing record so editing does not clear it.
Set(
    varEditHolder,
    {
        DisplayName: Coalesce(varEditAsset.CurrentHolder.DisplayName, ""),
        Mail: Coalesce(varEditAsset.CurrentHolder.Email, "")
    }
);
// Remember who held the asset, so only a real change gets logged.
Set(varOriginalHolderMail, Coalesce(varEditAsset.CurrentHolder.Email, ""));
// Maintenance dates are picked, never typed. Blank is a real value here:
// an asset can legitimately have no maintenance date yet.
Set(varEdLast, varEditAsset.LastMaintenanceDate);
Set(varEdNext, varEditAsset.NextMaintenanceDue);
Set(varEdPick, "");
// The chips work off a collection; seed it from the record being edited.
ClearCollect(
    colCommDone,
    ForAll(varEditAsset.CommissioningDone As c, { Value: c.Value })
);
// Setups is a multi-value Lookup, so it reads as a table of { Id, Value }.
// Editing happens on the collection; the column is written in one go on save.
Clear(colAssetSetups);
Collect(
    colAssetSetups,
    ForAll(varEditAsset.Setups As s, { Id: s.Id, Value: s.Value })
);
Set(
    varEdPickMonth,
    With(
        { seed: Coalesce(varEditAsset.LastMaintenanceDate, Today()) },
        Date(Year(seed), Month(seed), 1)
    )
)

If(
    IsBlank(LookUp(colAssetSetups, Value = ThisItem.Titel)),
    Collect(colAssetSetups, { Id: ThisItem.'Id (ID)', Value: ThisItem.Titel })
);
Reset(txtSetupSearch)

Set(
    varEdPickMonth,
    With(
        { seed: Coalesce(varEdLast, Today()) },
        Date(Year(seed), Month(seed), 1)
    )
);
Set(varEdPick, "last")

Set(
    varEdPickMonth,
    With(
        { seed: Coalesce(varEdNext, Today()) },
        Date(Year(seed), Month(seed), 1)
    )
);
Set(varEdPick, "next")

Set(
    varEditHolder,
    { DisplayName: ThisItem.DisplayName, Mail: ThisItem.Mail }
);
Reset(txtHolderSearch)

// Patch gets a literal record in each branch. Handing it a record bound
// with With() fails as "expecting a Record value, but of a different schema",
// and putting the If around Defaults() and an existing record instead unions
// two record types.
Set(
    varSavedAsset,
    If(
        varIsNewAsset,
        Patch(
            Equipment_Assets,
            Defaults(Equipment_Assets),
            {
            Titel:            Trim(txtAssetID.Text),
            DeviceName:       Trim(txtDeviceName.Text),
            SerialNumber:     Trim(txtSerialNumber.Text),
            UANumber:         Trim(txtUANumber.Text),
            // A multi-value Lookup is written as a table. ForAll gives it a
            // schema even when the collection is empty, which is how an asset
            // is taken out of every setup at once.
            Setups:           ForAll(
                                  colAssetSetups As s,
                                  {
                                      '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedReference",
                                      Id: s.Id,
                                      Value: s.Value
                                  }
                              ),
            Manufacturer:     Trim(txtManufacturer.Text),
            CommissioningRequired: { Value: drpEditCommReq.Selected.Value },
            CommissioningDone:     ForAll(colCommDone As c, { Value: c.Value }),
            CurrentCampus:    { Value: drpEditCampus.Selected.Value },
            'CurrentLocation (CurrentLocation0)': { Value: drpEditLocation.Selected.Value },
            OwnerGroup:       { Value: drpEditOwner.Selected.Value },
            UserGroup:        { Value: drpEditUser.Selected.Value },
            Status:           { Value: drpEditStatus.Selected.Value },
            LastMaintenanceDate: varEdLast,
            NextMaintenanceDue:  varEdNext,
            LastUpdated:      Now()
            }
        ),
        Patch(
            Equipment_Assets,
            // LookUp by ID, not the variable itself: a record carried in a global
            // variable loses its schema, and Patch rejects it as "a Record value,
            // but of a different schema".
            LookUp(Equipment_Assets, 'Id (ID)' = varEditAsset.'Id (ID)'),
            {
            Titel:            Trim(txtAssetID.Text),
            DeviceName:       Trim(txtDeviceName.Text),
            SerialNumber:     Trim(txtSerialNumber.Text),
            UANumber:         Trim(txtUANumber.Text),
            // A multi-value Lookup is written as a table. ForAll gives it a
            // schema even when the collection is empty, which is how an asset
            // is taken out of every setup at once.
            Setups:           ForAll(
                                  colAssetSetups As s,
                                  {
                                      '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedReference",
                                      Id: s.Id,
                                      Value: s.Value
                                  }
                              ),
            Manufacturer:     Trim(txtManufacturer.Text),
            CommissioningRequired: { Value: drpEditCommReq.Selected.Value },
            CommissioningDone:     ForAll(colCommDone As c, { Value: c.Value }),
            CurrentCampus:    { Value: drpEditCampus.Selected.Value },
            'CurrentLocation (CurrentLocation0)': { Value: drpEditLocation.Selected.Value },
            OwnerGroup:       { Value: drpEditOwner.Selected.Value },
            UserGroup:        { Value: drpEditUser.Selected.Value },
            Status:           { Value: drpEditStatus.Selected.Value },
            LastMaintenanceDate: varEdLast,
            NextMaintenanceDue:  varEdNext,
            LastUpdated:      Now()
            }
        )
    )
);

// Person field separately, so an empty pick does not clear the existing value.
If(
    !IsBlank(varEditHolder.Mail) && !IsBlank(varSavedAsset.'Id (ID)'),
    Patch(
        Equipment_Assets,
        // LookUp by ID, not the variable itself: a record carried in a global
        // variable loses its schema, and Patch rejects it as "a Record value,
        // but of a different schema".
        LookUp(Equipment_Assets, 'Id (ID)' = varSavedAsset.'Id (ID)'),
        {
            CurrentHolder: {
                '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                Claims: "i:0#.f|membership|" & Lower(varEditHolder.Mail),
                DisplayName: varEditHolder.DisplayName,
                Email: varEditHolder.Mail,
                Department: "",
                JobTitle: "",
                Picture: ""
            }
        }
    )
);

// A change of holder belongs in the asset history.
// Equipment_MovementLog has AssignedUser and the choice value
// "Handover/Assignment" for exactly this.
If(
    !IsBlank(varEditHolder.Mail)
        && varEditHolder.Mail <> varOriginalHolderMail
        && !IsBlank(varSavedAsset.'Id (ID)'),
    Patch(
        Equipment_MovementLog,
        Defaults(Equipment_MovementLog),
        {
            Title: Trim(txtAssetID.Text),
            ActionType: { Value: "Handover/Assignment" },
            TimeStamp: Now(),
            MovedBy: {
                '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                Claims: "i:0#.f|membership|" & Lower(User().Email),
                DisplayName: User().FullName,
                Email: User().Email,
                Department: "",
                JobTitle: "",
                Picture: ""
            },
            AssignedUser: {
                '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                Claims: "i:0#.f|membership|" & Lower(varEditHolder.Mail),
                DisplayName: varEditHolder.DisplayName,
                Email: varEditHolder.Mail,
                Department: "",
                JobTitle: "",
                Picture: ""
            }
        }
    )
);

If(
    IsEmpty(Errors(Equipment_Assets)),
    Notify(
        If(varIsNewAsset, "Asset added.", "Changes saved."),
        NotificationType.Success
    );
    Set(varCurrentAsset, LookUp(Equipment_Assets, 'Id (ID)' = varSavedAsset.'Id (ID)'));
    Set(varEditAsset, Blank());
    Navigate(scr_AssetDetail, ScreenTransition.Fade),
    Notify(
        "Save failed: " & Concat(Errors(Equipment_Assets), Message, " | "),
        NotificationType.Error
    )
)

With(
    {
        first: DateAdd(
            varEdPickMonth,
            -(Weekday(varEdPickMonth, StartOfWeek.Monday) - 1),
            TimeUnit.Days
        )
    },
    ForAll(
        Sequence(42) As s,
        With(
            { d: DateAdd(first, s.Value - 1, TimeUnit.Days) },
            {
                CellDate: d,
                DayNum: Day(d),
                InMonth: Month(d) = Month(varEdPickMonth)
            }
        )
    )
)

If(
    varEdPick = "last",
    Set(varEdLast, ThisItem.CellDate),
    Set(varEdNext, ThisItem.CellDate)
);
Set(varEdPick, "")

If(
    varEdPick = "last",
    Set(varEdLast, ThisItem.CellDate),
    Set(varEdNext, ThisItem.CellDate)
);
Set(varEdPick, "")
